import {
  calculateAngles,
  calculatePlanetaryChart,
  calculatePorphyryCusps,
  resolveBirthDate,
} from '../astroEngine';

/**
 * Independent reference values generated by Astrodienst's official Swiss
 * Ephemeris `swetest` endpoint (version 2.10.03) on 2026-10-22.
 *
 * Command shape used for every fixture:
 *   swetest -b<DD.MM.YYYY> -ut<HH:MM> -n1
 *     -house<longitude>,<latitude>,O -p0123456789 -fPl -g, -head
 *
 * `O` is the Porphyry house system. The checked-in values intentionally keep
 * the test deterministic and offline; updating them must be done from the
 * official reference, never from the implementation under test.
 */

const PLANET_TOLERANCE_DEGREES = 0.03;
const ANGLE_TOLERANCE_DEGREES = 0.05;

interface SwissReferenceFixture {
  id: string;
  utc: string;
  latitude: number;
  longitude: number;
  planets: Record<string, number>;
  ascendant: number;
  midheaven: number;
  houseCusps: number[];
}

