function circularDifference(actual: number, expected: number): number {
  const difference = Math.abs(actual - expected) % 360;
  return Math.min(difference, 360 - difference);
}

function expectCircularlyClose(
  actual: number,
  expected: number,
  tolerance: number,
  label: string
): void {
  const difference = circularDifference(actual, expected);
  if (difference > tolerance) {
    throw new Error(
      `${label}: expected ${expected.toFixed(7)}°, received ${actual.toFixed(7)}° `
      + `(circular difference ${difference.toFixed(7)}°, tolerance ${tolerance}°)`
    );
  }
}

describe('Swiss Ephemeris independent reference audit', () => {
  it.each(SWISS_REFERENCE_FIXTURES)(
    'keeps planetary longitudes within the declared tolerance: $id',
    (fixture) => {
      const chart = calculatePlanetaryChart(new Date(fixture.utc));

      for (const [planet, expectedLongitude] of Object.entries(fixture.planets)) {
        expectCircularlyClose(
          chart.planets[planet].longitude,
          expectedLongitude,
          PLANET_TOLERANCE_DEGREES,
          `${fixture.id}/${planet}`
        );
      }
    }
  );

  it.each(SWISS_REFERENCE_FIXTURES)(
    'keeps ASC, MC and Porphyry cusps within the declared tolerance: $id',
    (fixture) => {
      const date = new Date(fixture.utc);
      const angles = calculateAngles(date, fixture.latitude, fixture.longitude);
      const cusps = calculatePorphyryCusps(angles);

      expectCircularlyClose(
        angles.ascendant,
        fixture.ascendant,
        ANGLE_TOLERANCE_DEGREES,
        `${fixture.id}/Ascendant`
      );
      expectCircularlyClose(
        angles.midheaven,
        fixture.midheaven,
        ANGLE_TOLERANCE_DEGREES,
        `${fixture.id}/MC`
      );
      cusps.forEach((cusp, index) => {
        expectCircularlyClose(
          cusp.longitude,
          fixture.houseCusps[index],
          ANGLE_TOLERANCE_DEGREES,
          `${fixture.id}/house-${cusp.house}`
        );
      });
    }
  );

  it('resolves the first occurrence of New York repeated 01:30 to the audited UTC instant', () => {
    const resolved = resolveBirthDate('2024-11-03', '01:30', 'exact', {
      placeId: 'new-york',
      userLabel: 'New York, USA',
      latitude: 40.7128,
      longitude: -74.006,
      timeZoneIdentifier: 'America/New_York',
      resolvedAt: '2026-10-22T00:00:00.000Z',
    });

    expect(resolved.date.toISOString()).toBe('2024-11-03T05:30:00.000Z');
    expect(resolved.isLocalTimeAmbiguous).toBe(true);
  });
});
